NooriEditor::~NooriEditor(){stopTimer();setLookAndFeel(nullptr);}
void NooriEditor::setupSlider(juce::Slider& s,juce::Label& l,juce::String label,double min,double max,double step,juce::String suffix){addAndMakeVisible(s);addAndMakeVisible(l);s.setName(label);l.setText(label,juce::dontSendNotification);l.setColour(juce::Label::textColourId,muted);s.setRange(min,max,step);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,75,20);s.setTextValueSuffix(suffix);s.onValueChange=[this,label]{pullControls(label,true);};s.onDragStart=[this]{session->journal->beginGroup();};s.onDragEnd=[this]{session->journal->endGroup();};}
void NooriEditor::syncControls(){matchTarget.setSelectedId(session->useReference?3:session->exactBpm?1:2,juce::dontSendNotification);auto s=session->settings;if(session->useReference||session->exactBpm){s.strength=1;s.humanizeMs=0;s.toleranceMs=0;s.swing=0;s.offsetMs=0;s.sampleAccurate=true;s.emotionalProtection=false;}grid.setSelectedId(s.division==4?1:s.division==8?2:s.division==16?3:4,juce::dontSendNotification);rhythm.setSelectedId((int)s.rhythm+1,juce::dontSendNotification);mode.setSelectedId(s.percussion?3:s.naturalNaat?2:1,juce::dontSendNotification);sensitivity.setValue(s.sensitivity*100,juce::dontSendNotification);strength.setValue(s.strength*100,juce::dontSendNotification);humanize.setValue(s.humanizeMs,juce::dontSendNotification);tolerance.setValue(s.toleranceMs,juce::dontSendNotification);swing.setValue(s.swing*100,juce::dontSendNotification);offset.setValue(s.offsetMs,juce::dontSendNotification);sampleAccurate.setToggleState(s.sampleAccurate,juce::dontSendNotification);breath.setToggleState(s.breathProtection,juce::dontSendNotification);consonant.setToggleState(s.consonantProtection,juce::dontSendNotification);vowel.setToggleState(s.vowelProtection,juce::dontSendNotification);emotion.setToggleState(s.emotionalProtection,juce::dontSendNotification);}
void NooriEditor::pullControls(juce::String label,bool merge){edit(label,[&]{auto& s=session->settings;s.division=grid.getSelectedId()==1?4:grid.getSelectedId()==2?8:grid.getSelectedId()==3?16:32;s.rhythm=(noori::Settings::Rhythm)(rhythm.getSelectedId()-1);s.naturalNaat=mode.getSelectedId()==2;s.percussion=mode.getSelectedId()==3;s.sensitivity=sensitivity.getValue()/100;if(!session->exactBpm&&!session->useReference){s.strength=strength.getValue()/100;s.humanizeMs=humanize.getValue();s.toleranceMs=tolerance.getValue();s.swing=swing.getValue()/100;s.offsetMs=offset.getValue();s.sampleAccurate=sampleAccurate.getToggleState();}s.breathProtection=breath.getToggleState();s.consonantProtection=consonant.getToggleState();s.vowelProtection=vowel.getToggleState();if(!session->exactBpm&&!session->useReference)s.emotionalProtection=emotion.getToggleState();},merge);session->status="Settings changed | detect attacks to refresh onsets, then align.";waveform.repaint();}
void NooriEditor::bindSession(std::shared_ptr<EditSession> s){if(s==session)return;session=std::move(s);session->journal=processor.insertSession->journal;if(targetID.isEmpty()){referenceID.clear();if(session->useReference&&session->referenceProjectID.isEmpty())referenceID="imported";}restoreUI();syncControls();updateScroll();}
void NooriEditor::timerCallback(){
 processor.insertSession->journal->finishIfIdle();
 if(seenSerial!=session->changeSerial&&!session->busy){seenSerial=session->changeSerial;restoreUI();syncControls();}
 if(!groupSessions.empty()&&std::none_of(groupSessions.begin(),groupSessions.end(),[](const auto& s){return s->busy.load();})){processor.insertSession->journal->endGroup();groupSessions.clear();}
 refreshProjectTracks();
#if JucePlugin_Enable_ARA
 if(targetID.isEmpty()&&processor.isEditorView())if(auto s=selectedARASession(processor))bindSession(s);
#endif
 bool batchBusy=false;for(const auto& s:groupSessions)batchBusy|=s->busy.load();for(const auto& s:batchSessions)batchBusy|=s->busy.load();
 if(!batchSessions.empty()&&!batchBusy){int failed=0,edgeEvents=0;juce::String error;for(const auto& s:batchSessions){if(s->status.contains("clip-edge"))++edgeEvents;if(!s->status.contains("ready")){++failed;error=s->status;}}batchStatus=juce::String((int)batchSessions.size()-failed)+" events completed; "+juce::String(failed)+" blocked"+(failed?" | "+error:"")+(edgeEvents?" | clip-edge attacks kept in "+juce::String(edgeEvents)+" events; inspect each preview status":"");batchSessions.clear();}
 const bool busy=session->busy||batchBusy||processor.insertSession->journal->hasPending();bool has=session->original!=nullptr;
 referenceButton.setEnabled(has&&!busy);matchTarget.setEnabled(!busy);targetTrack.setEnabled(!busy);targetEvent.setEnabled(!busy&&targetEvent.getNumItems()>0);referenceTrack.setEnabled(!busy);referenceAnalysis.setEnabled(has&&!busy);
 matchTarget.setSelectedId(session->useReference?3:session->exactBpm?1:2,juce::dontSendNotification);audition.setToggleState(processor.audition.load(),juce::dontSendNotification);
 for(auto* b:{&analyseButton,&exportButton,&compareButton,&selectAllButton,&clearSelectionButton})b->setEnabled(has&&!busy);
 selectAllButton.setEnabled(has&&!busy&&!session->attacks.empty());
 const int count=(int)std::count_if(session->attacks.begin(),session->attacks.end(),[](const auto& a){return a.selected;});
 addButton.setEnabled(has&&!busy);removeButton.setEnabled(has&&!busy&&count>0);themeButton.setEnabled(!busy);overlayButton.setEnabled(has&&!busy);selectedButton.setEnabled(has&&!busy&&count>0);selectedButton.setButtonText("Align selected attacks ("+juce::String(count)+")");selectedButton.setTooltip(count?"Quantize only the highlighted attack markers.":"Detect attacks, then click a marker, drag a range, or press Select all attacks.");
 undoButton.setEnabled(!busy&&session->canUndo());redoButton.setEnabled(!busy&&session->canRedo());undoButton.setTooltip("Undo: "+session->undoDescription());redoButton.setTooltip("Redo: "+session->redoDescription());
 bool ara=false;
#if JucePlugin_Enable_ARA
 ara=processor.isEditorView()||processor.isPlaybackRenderer();
#endif
 anchorButton.setEnabled(has&&!busy&&!ara&&processor.hostTempoValid);manualBpm.setEnabled(!processor.hostTempoValid&&!busy);if(processor.hostTempoValid)manualBpm.setValue(processor.bpm.load(),juce::dontSendNotification);
 importButton.setEnabled(!ara&&!busy&&!processor.captureArmed);captureButton.setEnabled(!ara&&!busy);audition.setEnabled(!ara&&has&&!processor.captureArmed);captureButton.setButtonText(processor.captureArmed?"Finish capture":"Capture");
 compareButton.setToggleState(session->compare.load(),juce::dontSendNotification);
 for(auto* c:std::initializer_list<juce::Component*>{&sensitivity,&strength,&humanize,&tolerance,&swing,&offset,&grid,&mode,&rhythm,&presets,&sampleAccurate,&breath,&consonant,&vowel,&emotion,&settingsButton})c->setEnabled(!busy);
 alignButton.setEnabled(!busy);
 if(session->useReference||session->exactBpm)for(auto* c:std::initializer_list<juce::Component*>{&strength,&humanize,&tolerance,&swing,&offset,&emotion,&sampleAccurate})c->setEnabled(false);
 if(session->useReference){grid.setEnabled(false);rhythm.setEnabled(false);}
 repaint();waveform.repaint();overview.repaint();
}
void NooriEditor::chooseFile(bool save){chooser=std::make_unique<juce::FileChooser>(save?"Export corrected 24-bit WAV":"Import mono or stereo vocal",juce::File(),save?"*.wav":"*.wav;*.aif;*.aiff;*.flac");auto flags=save?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles;chooser->launchAsync(flags,[safe=juce::Component::SafePointer<NooriEditor>(this),save](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File())return;if(save)safe->processor.exportFile(file,safe->session);else safe->processor.importFile(file);});}
void NooriEditor::scrollBarMoved(juce::ScrollBar*,double start){edit("Scroll",[&]{session->viewStart=start;},true);viewStart=start;waveform.repaint();overview.repaint();}
void NooriEditor::updateScroll(){scroll.setRangeLimits(0,1);scroll.setCurrentRange(viewStart,viewFraction,juce::dontSendNotification);}
