 auto status=processor.captureArmed?processor.captureStatus():batchStatus.isNotEmpty()?batchStatus:session->status;if(session->busy)status+="  "+juce::String((int)(session->progress*100))+"%";text(g,status,{22,getHeight()-34,getWidth()-45,23},12,muted);
 if(session->busy){g.setColour(purple);g.fillRect(22,getHeight()-9,(int)((getWidth()-44)*session->progress.load()),2);}
