NooriEditor::WaveView::WaveView(NooriEditor& e,bool o):editor(e),overview(o){setMouseCursor(juce::MouseCursor::CrosshairCursor);}
noori::Sample NooriEditor::WaveView::sampleAt(float x)const {if(!editor.session->original)return 0;double start=overview?0:editor.viewStart,frac=overview?1:editor.viewFraction;return (noori::Sample)std::llround((start+double(x)/getWidth()*frac)*editor.session->original->length());}
float NooriEditor::WaveView::xAt(noori::Sample s)const {if(!editor.session->original)return 0;return float((double(s)/editor.session->original->length()-(overview?0:editor.viewStart))/(overview?1:editor.viewFraction)*getWidth());}
void NooriEditor::WaveView::paint(juce::Graphics& g){const auto line=editor.line,muted=editor.muted,purple=editor.purple,ink=editor.ink;g.fillAll(editor.waveBg);auto* audio=editor.session->displayed();if(!audio){if(!overview){text(g,"Your vocal. Its original emotion.",{0,getHeight()/2-26,getWidth(),30},23,ink,juce::Justification::centred);text(g,"Import audio, capture the insert input, or select an ARA event.",{0,getHeight()/2+10,getWidth(),25},14,muted,juce::Justification::centred);}return;}

 if(!overview){const auto start=sampleAt(0),end=sampleAt((float)getWidth());auto& map=editor.session->timeline;auto origin=editor.session->origin;auto s=editor.session->settings;if(editor.session->exactBpm||editor.session->useReference){s.swing=0;s.offsetMs=0;}double step=4./s.division;if(s.rhythm==noori::Settings::Rhythm::triplet)step*=2./3;if(s.rhythm==noori::Settings::Rhythm::dotted)step*=1.5;auto first=(long long)std::floor(map.quarterAt(start+origin)/step)-1;auto last=(long long)std::ceil(map.quarterAt(end+origin)/step)+1;for(auto k=first;k<=last&&k<first+2000;++k){double q=k*step+(k%2?s.swing*step:0);float x=xAt(map.sampleAt(q)-origin+(noori::Sample)std::llround(s.offsetMs*.001*audio->sampleRate));g.setColour(k%editor.session->settings.division==0?line:line.withAlpha(.35f));g.drawVerticalLine((int)x,30.f,(float)getHeight());if(k%2==0)text(g,juce::String((int)std::floor(q/(editor.processor.numerator.load()*4./editor.processor.denominator.load()))+1)+":"+juce::String((int)std::llround((q-std::floor(q/(editor.processor.numerator.load()*4./editor.processor.denominator.load()))*(editor.processor.numerator.load()*4./editor.processor.denominator.load()))*editor.processor.denominator.load()/4.)+1),{(int)x+4,2,65,21},11,muted);}}
 auto drawAudio=[&](const noori::Audio* a,int laneTop,int laneBottom,juce::Colour colour){if(!a)return;float center=(laneTop+laneBottom)*.5f,amp=(laneBottom-laneTop)*.40f;
 for(int x=0;x<getWidth();++x){auto first=std::clamp<noori::Sample>(sampleAt((float)x),0,a->length()-1),last=std::clamp<noori::Sample>(sampleAt((float)(x+1)),first+1,a->length());float low=0,high=0;double energy=0;int count=0;auto stride=std::max<noori::Sample>(1,(last-first)/64);for(auto i=first;i<last;i+=stride){float v=a->channels[0][(std::size_t)i];low=std::min(low,v);high=std::max(high,v);energy+=double(v)*v;++count;}g.setColour(colour);if(editor.levelView&&!overview){float rms=(float)std::sqrt(energy/std::max(1,count));g.drawVerticalLine(x,center-rms*amp*2,center+rms*amp*2);}else g.drawVerticalLine(x,center-high*amp,center-low*amp);}};
 if(overview){drawAudio(editor.session->audible.load(),0,getHeight(),muted);g.setColour(purple.withAlpha(.2f));g.fillRect((float)(editor.viewStart*getWidth()),0.f,(float)(editor.viewFraction*getWidth()),(float)getHeight());g.setColour(purple);g.drawRect((float)(editor.viewStart*getWidth()),0.f,(float)(editor.viewFraction*getWidth()),(float)getHeight(),1.f);}
 else {
  const int split=65+(getHeight()-65)/2;
  g.setColour(line);g.drawHorizontalLine(64,0.f,(float)getWidth());g.drawHorizontalLine(split,0.f,(float)getWidth());
  drawAudio(editor.session->original.get(),65,split,muted.withAlpha(.8f));drawAudio(editor.session->audible.load(),split,getHeight(),purple.withAlpha(.85f));
  if(editor.session->overlay&&editor.session->referenceAudio){auto& a=*editor.session->referenceAudio;float center=(split+getHeight())*.5f,amp=(getHeight()-split)*.40f;juce::Path top,bottom;for(int x=0;x<getWidth();++x){auto first=std::clamp<noori::Sample>(sampleAt((float)x),0,a.length()-1),last=std::clamp<noori::Sample>(sampleAt((float)x+1),first+1,a.length());float lo=0,hi=0;for(auto i=first;i<last;i+=std::max<noori::Sample>(1,(last-first)/64)){auto v=a.channels[0][(std::size_t)i];lo=std::min(lo,v);hi=std::max(hi,v);}if(x==0){top.startNewSubPath(0,center-hi*amp);bottom.startNewSubPath(0,center-lo*amp);}else {top.lineTo((float)x,center-hi*amp);bottom.lineTo((float)x,center-lo*amp);}}g.setColour(editor.referenceColour);g.strokePath(top,juce::PathStrokeType(1.2f));g.strokePath(bottom,juce::PathStrokeType(1.2f));}

  for(auto click:editor.session->referenceClicks){float x=xAt(click);if(x>=0&&x<getWidth()){g.setColour(editor.referenceColour);g.drawVerticalLine((int)x,32.f,64.f);if(editor.session->useReference){g.setColour(editor.referenceColour.withAlpha(.25f));g.drawVerticalLine((int)x,65.f,(float)getHeight());g.setColour(editor.referenceColour);}g.fillEllipse(x-2,33,4,4);}}
  text(g,editor.session->referenceName.isEmpty()?"REFERENCE | import rendered metronome WAV":"REFERENCE | "+editor.session->referenceName,{8,31,getWidth()-16,20},11,editor.referenceColour);
  text(g,"ORIGINAL | source attacks",{8,67,260,20},11,muted);text(g,"CORRECTED | drag attacks",{8,split+2,260,20},11,purple);
  for(std::size_t i=0;i<editor.session->attacks.size();++i){auto a=editor.session->attacks[i];auto target=(int)i==dragging?dragTarget:a.target;float sx=xAt(a.source),tx=xAt(target);g.setColour(muted);if(sx>=0&&sx<=getWidth()){g.drawVerticalLine((int)sx,90.f,(float)split);g.fillEllipse(sx-3,91,6,6);}g.setColour(a.selected?juce::Colour(editor.session->lightTheme?0xff986100:0xffffce79):purple);if(tx>=0&&tx<=getWidth()){g.drawVerticalLine((int)tx,(float)split+24,(float)getHeight());g.fillEllipse(tx-3,(float)split+25,6,6);}g.setColour(purple.withAlpha(.35f));g.drawLine(sx,(float)split-7,tx,(float)split+24);}
 }

 if(rangeSelecting){auto left=std::min(rangeStart,rangeEnd),right=std::max(rangeStart,rangeEnd);g.setColour(purple.withAlpha(.16f));g.fillRect(left,65.f,right-left,(float)getHeight()-65);g.setColour(purple);g.drawRect(left,65.f,right-left,(float)getHeight()-65);}
 const auto position=editor.processor.hostSample.load();const double srRatio=audio->sampleRate/std::max(1.,editor.processor.getSampleRate());auto at=(noori::Sample)std::llround(position*srRatio)-editor.session->origin;auto px=xAt(at);if(px>=0&&px<getWidth()){g.setColour(juce::Colour(editor.session->lightTheme?0xff986100:0xffffd87b));g.drawVerticalLine((int)px,0.f,(float)getHeight());}
}
void NooriEditor::WaveView::mouseDown(const juce::MouseEvent& e){if(!editor.session->original||editor.session->busy)return;if(overview){mouseDrag(e);return;}editor.grabKeyboardFocus();if(editor.addingAttack){editor.session->addAttack(sampleAt(e.position.x));editor.addingAttack=false;editor.addButton.setToggleState(false,juce::dontSendNotification);editor.addButton.setButtonText("Add attack");return;}float best=9;int nearest=-1;const bool original=e.position.y<65+(getHeight()-65)/2;for(std::size_t i=0;i<editor.session->attacks.size();++i){auto a=editor.session->attacks[i];auto d=std::abs(xAt(original?a.source:a.target)-e.position.x);if(d<best){best=d;nearest=(int)i;}}if(nearest>=0){editor.session->setSelected((std::size_t)nearest,e.mods.isShiftDown());editor.selectedMarker=nearest;if(!original){dragging=nearest;dragTarget=editor.session->attacks[(std::size_t)nearest].target;}}else{rangeSelecting=true;sourceRange=original;additiveRange=e.mods.isShiftDown();rangeStart=rangeEnd=e.position.x;if(!additiveRange)editor.session->selectAll(false);}editor.timerCallback();repaint();}
void NooriEditor::WaveView::mouseDrag(const juce::MouseEvent& e){if(!editor.session->original)return;if(overview){editor.edit("Scroll",[&]{editor.session->viewStart=std::clamp(double(e.position.x)/getWidth()-editor.viewFraction*.5,0.,1-editor.viewFraction);},true);editor.viewStart=editor.session->viewStart;editor.updateScroll();editor.waveform.repaint();repaint();}else if(rangeSelecting){rangeEnd=e.position.x;repaint();}else if(dragging>=0){try{auto m=noori::moveAttack(editor.session->attacks,(std::size_t)dragging,sampleAt(e.position.x),editor.session->original->length(),editor.session->settings.maxStretch);dragTarget=m[(std::size_t)dragging].target;repaint();}catch(...){}}}
void NooriEditor::WaveView::mouseUp(const juce::MouseEvent&){if(rangeSelecting){editor.session->selectRange(sampleAt(rangeStart),sampleAt(rangeEnd),additiveRange,sourceRange);rangeSelecting=false;editor.timerCallback();}if(dragging>=0){if(dragTarget!=editor.session->attacks[(std::size_t)dragging].target)editor.session->move((std::size_t)dragging,dragTarget);dragging=-1;}repaint();}
void NooriEditor::WaveView::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& d){if(e.mods.isCtrlDown())editor.zoom.setValue(editor.zoom.getValue()*(d.deltaY>0?1.15:1/1.15));else {editor.edit("Scroll",[&]{editor.session->viewStart=std::clamp(editor.viewStart-d.deltaY*editor.viewFraction*.3,0.,1-editor.viewFraction);},true);editor.viewStart=editor.session->viewStart;editor.updateScroll();editor.waveform.repaint();editor.overview.repaint();}}

bool NooriEditor::keyPressed(const juce::KeyPress& key){if(key.getModifiers().isCommandDown()){if(key.getKeyCode()=='A'){session->selectAll();timerCallback();return true;}if(key.getKeyCode()=='Z'){historyStep(key.getModifiers().isShiftDown());return true;}if(key.getKeyCode()=='Y'){historyStep(true);return true;}}if(key.getKeyCode()==juce::KeyPress::deleteKey||key.getKeyCode()==juce::KeyPress::backspaceKey){session->removeSelectedAttacks();return true;}if(key.getKeyCode()==juce::KeyPress::escapeKey){session->selectAll(false);timerCallback();return true;}return false;}

void NooriEditor::syncTempo(){if(!session->original||session->busy||session->timeline.points().size()!=1)return;auto t=processor.transport();auto rate=session->original->sampleRate;try{if(t.valid){auto at=(noori::Sample)std::llround(t.sample*rate/std::max(1.,processor.getSampleRate()));session->timeline=noori::Timeline(rate,{{at,t.bpm,t.quarter}});}else session->timeline=noori::Timeline(rate,{{0,manualBpm.getValue(),0}});}catch(const std::exception& e){session->status=juce::String::fromUTF8(e.what());}}
void NooriEditor::refreshProjectTracks(){
 std::vector<ProjectTrack> current;
#if JucePlugin_Enable_ARA
 current=availableProjectTracks(processor);if(!processor.isEditorView())current=processor.connectedReferenceTracks();
#else
 current=processor.connectedReferenceTracks();
#endif
 juce::String signature;for(const auto& t:current){signature+=t.id+t.name;for(const auto& r:t.regions)signature+=r.id+r.name;}
 if((referenceID.isEmpty()||referenceID=="imported")&&session->useReference&&session->referenceProjectID.isNotEmpty()){for(const auto& t:current)if(t.persistentID==session->referenceProjectID){referenceID=t.id;referenceAnalysis.setSelectedId(session->referenceIsClick?1:2,juce::dontSendNotification);break;}if(referenceID.isEmpty())referenceID="imported";}
 const bool changed=signature!=inventory||targetTrack.getNumItems()==0;projectTracks=std::move(current);
 if(changed){inventory=signature;targetTrack.clear(juce::dontSendNotification);referenceTrack.clear(juce::dontSendNotification);
  const bool editable=std::any_of(projectTracks.begin(),projectTracks.end(),[](const auto& t){return t.editable;});targetTrack.addItem(editable?"Edit: follow Cubase selection":"Edit: this insert vocal",1);
  referenceTrack.addItem("DAW bar/beat | BPM grid",1);referenceTrack.addItem("Imported reference file",2);
  for(std::size_t i=0;i<projectTracks.size();++i){if(projectTracks[i].editable)targetTrack.addItem("Edit: "+projectTracks[i].name,100+(int)i);referenceTrack.addItem(projectTracks[i].name,100+(int)i);}
  if(projectTracks.empty()){referenceTrack.addItem("ARA tracks or another captured NOORI insert required",3);referenceTrack.setItemEnabled(3,false);}
 }
 int target=1,reference=referenceID=="imported"?2:1;for(std::size_t i=0;i<projectTracks.size();++i){if(projectTracks[i].id==targetID)target=100+(int)i;if(projectTracks[i].id==referenceID)reference=100+(int)i;}
 if(target==1&&!targetID.isEmpty()){targetID.clear();targetEvent.clear(juce::dontSendNotification);bindSession(processor.insertSession);session->status="Selected project track was removed; follow Cubase selection.";}
 if(reference==1&&!referenceID.isEmpty()&&referenceID!="imported"){referenceID.clear();session->useReference=false;session->status="Reference track is no longer connected or exposed. Choose another reference.";}
 targetTrack.setSelectedId(target,juce::dontSendNotification);referenceTrack.setSelectedId(reference,juce::dontSendNotification);
 if(target==1){targetEvent.clear(juce::dontSendNotification);targetEvent.setTextWhenNothingSelected("Preview: "+session->name);}
}
void NooriEditor::chooseTarget(){batchStatus.clear();auto it=std::find_if(projectTracks.begin(),projectTracks.end(),[this](const auto& t){return t.id==targetID;});if(it==projectTracks.end()){
#if JucePlugin_Enable_ARA
 if(auto s=selectedARASession(processor)){bindSession(s);return;}
#endif
 bindSession(processor.insertSession);return;}
 int event=std::clamp(targetEvent.getSelectedId()-1,0,(int)it->regions.size()-1);targetEvent.clear(juce::dontSendNotification);for(std::size_t i=0;i<it->regions.size();++i)targetEvent.addItem("Preview: "+it->regions[i].name,1+(int)i);targetEvent.setSelectedId(event+1,juce::dontSendNotification);auto& region=it->regions[(std::size_t)event];
#if JucePlugin_Enable_ARA
 configureProjectRegion(processor,region.id);
#endif
 bindSession(region.session);if(!referenceID.isEmpty())chooseReference();timerCallback();
}
std::vector<ProjectReferenceRegion> NooriEditor::referenceSnapshot()const {std::vector<ProjectReferenceRegion> result;for(const auto& t:projectTracks)if(t.id==referenceID)for(const auto& r:t.regions)result.push_back({r.session->snapshot(),r.sourceStart,r.sourceDuration,r.playbackStart});return result;}
void NooriEditor::chooseReference(){batchStatus.clear();int choice=referenceTrack.getSelectedId();if(choice==1){edit("Reference: BPM grid",[&]{referenceID.clear();session->useReference=false;session->exactBpm=true;});syncControls();return;}if(choice==2){edit("Reference: imported file",[&]{if(session->referenceProjectID.isNotEmpty()){session->referenceClicks.clear();session->referenceName.clear();session->referenceProjectID.clear();}referenceID="imported";session->useReference=true;});syncControls();return;}int index=choice-100;if(index<0||index>=(int)projectTracks.size())return;auto& track=projectTracks[(std::size_t)index];if(track.id==targetID){session->status="Choose a different reference track from the edit track.";return;}referenceID=track.id;session->loadProjectReference(referenceSnapshot(),track.name,referenceAnalysis.getSelectedId()==1,false,false,{},track.persistentID);syncControls();}
void NooriEditor::performAlign(bool selectedOnly){
 if(!session->original){session->status="Load vocal audio first: use ARA on the audio event, Import vocal, or Capture / Finish. An insert cannot read the track automatically.";return;}if(session->busy){session->status="Audio is still processing. Wait for ready, then align.";return;}batchStatus.clear();syncTempo();
 struct Target{std::shared_ptr<EditSession> session;juce::String region;double offset;AttackRange range;};std::vector<Target> targets;
 if(!selectedOnly&&!targetID.isEmpty()){for(const auto& t:projectTracks)if(t.id==targetID)for(const auto& r:t.regions){auto offset=r.playbackStart-r.sourceStart;auto found=std::find_if(targets.begin(),targets.end(),[&](const auto& a){return a.session==r.session;});if(found!=targets.end()){if(!r.session->original||std::abs(found->offset-offset)>1e-6||!found->range||found->range->first!=(noori::Sample)std::llround(r.sourceStart*r.session->original->sampleRate)||found->range->second!=(noori::Sample)std::llround((r.sourceStart+r.sourceDuration)*r.session->original->sampleRate)){session->status="Track contains shared audio at different project starts. Make independent event copies before track quantization.";return;}continue;}auto rate=r.session->original?r.session->original->sampleRate:48000;targets.push_back({r.session,r.id,offset,{{(noori::Sample)std::llround(r.sourceStart*rate),(noori::Sample)std::llround((r.sourceStart+r.sourceDuration)*rate)}}});}}
 if(targets.empty())targets.push_back({session,{},session->origin/session->original->sampleRate});
 for(const auto& t:targets)if(!t.session->original||t.session->busy){session->status="An edit-track event is still loading or processing. Try again shortly.";return;}
 const bool reference=session->useReference;const bool strict=session->exactBpm;const auto settings=session->settings;auto snapshots=referenceSnapshot();
 if(reference&&referenceID!="imported"&&referenceID.isNotEmpty()){if(snapshots.empty()||std::any_of(snapshots.begin(),snapshots.end(),[](const auto& r){return !r.audio;})){session->status="Reference not ready: enable ARA on its audio events, or Capture / Finish on its connected NOORI insert.";return;}}
 else if(reference&&session->referenceClicks.empty()){session->status="Choose a project reference track or import a reference file first.";return;}
 const auto imported=session->referenceClicks;const double importedRate=session->original->sampleRate;const auto importedOrigin=session->origin;const auto importedName=session->referenceName;
 processor.insertSession->journal->beginGroup(true);
 for(const auto& t:targets){auto s=t.session;groupSessions.push_back(s);s->journal=processor.insertSession->journal;
#if JucePlugin_Enable_ARA
 if(t.region.isNotEmpty()&&!configureProjectRegion(processor,t.region))continue;
#endif
 s->change("Track alignment settings",[&]{if(s->timeline.points().size()==1){auto transport=processor.transport();auto rate=s->original->sampleRate;if(transport.valid)s->timeline=noori::Timeline(rate,{{(noori::Sample)std::llround(transport.sample*rate/std::max(1.,processor.getSampleRate())),transport.bpm,transport.quarter}});else s->timeline=noori::Timeline(rate,{{0,manualBpm.getValue(),0}});}
 s->settings=settings;s->exactBpm=strict;s->useReference=reference;});
 if(reference&&referenceID!="imported"&&referenceID.isNotEmpty()){juce::String title,key;for(const auto& track:projectTracks)if(track.id==referenceID){title=track.name;key=track.persistentID;}s->loadProjectReference(snapshots,title,referenceAnalysis.getSelectedId()==1,true,selectedOnly,t.range,key);}
 else {if(reference&&s!=session){s->change("Reference mapping",[&]{s->referenceClicks.clear();for(auto click:imported)s->referenceClicks.push_back((noori::Sample)std::llround((click+importedOrigin)*s->original->sampleRate/importedRate)-s->origin);s->referenceName=importedName;});}s->align(selectedOnly,t.range);}
 if(targets.size()>1)batchSessions.push_back(s);
 }
 session->audition=true;processor.audition=true;audition.setToggleState(true,juce::dontSendNotification);if(targets.size()>1)batchStatus="Quantizing "+juce::String((int)targets.size())+" event sessions...";
}

void NooriEditor::WaveView::mouseDoubleClick(const juce::MouseEvent& e){if(!overview&&e.position.y<65+(getHeight()-65)/2)editor.session->addAttack(sampleAt(e.position.x));}
void NooriEditor::edit(juce::String label,std::function<void()> action,bool merge){session->change(label,std::move(action),merge);}
void NooriEditor::historyStep(bool redo){if(redo?!session->canRedo():!session->canUndo())return;if(redo)session->redo();else session->undo();if(auto restored=session->journal->restoredSession.lock()){if(restored!=session){targetID.clear();for(const auto& t:projectTracks)for(const auto& r:t.regions)if(r.session==restored)targetID=t.id;bindSession(restored);}}batchStatus.clear();restoreUI();syncControls();timerCallback();}
void NooriEditor::restoreUI(){viewStart=session->viewStart;viewFraction=1/session->viewZoom;levelView=session->levelView;zoom.setValue(session->viewZoom,juce::dontSendNotification);manualBpm.setValue(session->manualBpm,juce::dontSendNotification);presets.setSelectedId(session->preset,juce::dontSendNotification);overlayButton.setToggleState(session->overlay,juce::dontSendNotification);processor.audition=session->audition;referenceID.clear();if(session->useReference){referenceID="imported";for(const auto& t:projectTracks)if(t.persistentID==session->referenceProjectID)referenceID=t.id;}referenceAnalysis.setSelectedId(session->referenceIsClick?1:2,juce::dontSendNotification);applyTheme();updateScroll();}
void NooriEditor::applyTheme(){
 if(loadedLogo!=session->logoPNG){loadedLogo=session->logoPNG;logo=loadedLogo?juce::ImageFileFormat::loadFrom(loadedLogo->getData(),loadedLogo->getSize()):juce::Image();}
 const bool light=session->lightTheme;
 bg=juce::Colour(light?0xfff5f7fb:0xff14121d);panel=juce::Colour(light?0xffffffff:0xff1c1928);line=juce::Colour(light?0xffc7d0df:0xff464154);muted=juce::Colour(light?0xff526075:0xffb4aec4);purple=juce::Colour(light?0xff0969b5:0xff65baff);ink=juce::Colour(light?0xff182a42:0xfff2efff);waveBg=juce::Colour(light?0xfffafcff:0xff15121e);referenceColour=juce::Colour(light?0xff087b63:0xff65cfad);
 const auto control=juce::Colour(light?0xffedf2f8:0xff30293f);
 look.setColour(juce::TextButton::buttonColourId,control);look.setColour(juce::TextButton::buttonOnColourId,purple.withAlpha(.2f));look.setColour(juce::TextButton::textColourOffId,ink);look.setColour(juce::TextButton::textColourOnId,ink);
 look.setColour(juce::ComboBox::backgroundColourId,control);look.setColour(juce::ComboBox::textColourId,ink);look.setColour(juce::ComboBox::outlineColourId,line);look.setColour(juce::ComboBox::arrowColourId,ink);
 look.setColour(juce::PopupMenu::backgroundColourId,panel);look.setColour(juce::PopupMenu::textColourId,ink);look.setColour(juce::PopupMenu::highlightedBackgroundColourId,purple);look.setColour(juce::PopupMenu::highlightedTextColourId,juce::Colours::white);
 look.setColour(juce::Slider::thumbColourId,purple);look.setColour(juce::Slider::trackColourId,purple);look.setColour(juce::Slider::backgroundColourId,line);look.setColour(juce::Slider::textBoxTextColourId,ink);look.setColour(juce::Slider::textBoxBackgroundColourId,panel);look.setColour(juce::Slider::textBoxOutlineColourId,line);
 look.setColour(juce::ToggleButton::tickColourId,purple);look.setColour(juce::ToggleButton::textColourId,ink);look.setColour(juce::ToggleButton::tickDisabledColourId,muted);look.setColour(juce::TextEditor::textColourId,ink);look.setColour(juce::TextEditor::backgroundColourId,panel);
 for(auto* l:{&gridLabel,&rhythmLabel,&modeLabel,&sensitivityLabel,&strengthLabel,&humanizeLabel,&toleranceLabel,&swingLabel,&offsetLabel})l->setColour(juce::Label::textColourId,muted);
 alignButton.setColour(juce::TextButton::buttonColourId,purple);alignButton.setColour(juce::TextButton::textColourOffId,light?juce::Colours::white:juce::Colour(0xff10253d));attackTab.setColour(juce::TextButton::buttonColourId,levelView?control:purple);attackTab.setColour(juce::TextButton::textColourOffId,levelView?ink:light?juce::Colours::white:juce::Colour(0xff10253d));levelTab.setColour(juce::TextButton::buttonColourId,levelView?purple:control);levelTab.setColour(juce::TextButton::textColourOffId,levelView?(light?juce::Colours::white:juce::Colour(0xff10253d)):ink);themeButton.setButtonText(light?"Dark theme":"Light theme");sendLookAndFeelChange();repaint();waveform.repaint();overview.repaint();
}
